    @Override public void onCreate(Bundle state){super.onCreate(state); getWindow().setStatusBarColor(BG); getWindow().setNavigationBarColor(BG); prefs=getSharedPreferences("studio",MODE_PRIVATE); profiles=object(prefs.getString("profiles","{}")); bindings=object(prefs.getString("bindings","{}")); history=array(prefs.getString("history","[]")); nfc=NfcAdapter.getDefaultAdapter(this); pending=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE); home(); handle(getIntent());}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handle(intent);}
    @Override protected void onResume(){super.onResume(); if(nfc!=null&&nfc.isEnabled())try{nfc.enableForegroundDispatch(this,pending,null,null);}catch(Exception ignored){} }
