    static JSONObject object(String s){try{return new JSONObject(s);}catch(Exception e){return new JSONObject();}}
    static JSONArray array(String s){try{return new JSONArray(s);}catch(Exception e){return new JSONArray();}}
    static void put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(JSONException e){throw new IllegalArgumentException(e);}}
    void save(){prefs.edit().putString("profiles",profiles.toString()).putString("bindings",bindings.toString()).putString("history",history.toString()).apply();}
    int dp(int n){return (int)(getResources().getDisplayMetrics().density*n+0.5f);}
    TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));return t;}
    void page(String title,String sub){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(20),dp(24),dp(20),dp(24));root.setBackgroundColor(BG);sc.addView(root);setContentView(sc);TextView h=text(title,30,INK);h.setTypeface(null,Typeface.BOLD);root.addView(h);root.addView(text(sub,14,MUTED));}
    void label(String s){root.addView(text(s,17,INK));}
    void section(String s){TextView t=text(s,20,ACCENT);t.setTypeface(null,Typeface.BOLD);root.addView(t);}
    void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(INK);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(PANEL));b.setPadding(dp(12),dp(10),dp(12),dp(10));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(4),0,dp(4));root.addView(b,lp);b.setOnClickListener(v->r.run());}
